item.aggregated_output:
  in
  if normalized_length < min_anchor_length then
    ksprintf failwith
      "Anchor is too short: after collapsing whitespace, must be at least %d \
       byte(s), got %d"
      min_anchor_length normalized_length;
  let range = { T.start; end_ } in
  let new_anchor : Internal_types.anchor =
    {
      (* Placeholder; [DB.Anchors.create] generates the ID. *)
      anchor_id = App_types.Anchor_id.of_int_exn 0;
      doc_id = doc_meta.doc_id;
      doc_revision = doc_meta.revision;
      doc_revision_attempt = doc_meta.revision;
      acknowledged_revision = None;
      range;
      raw_contents = anchor_contents;
      last_author = T.Agent;
    }
  in
  DB.Anchors.create db new_anchor |> to_public_anchor db

let delete_anchor db (anchor_id : T.anchor_id) : unit =
  DB.Anchors.delete db anchor_id

let get_anchor db (anchor_id : T.anchor_id) : anchor option =
  DB.Anchors.get db anchor_id |> Option.map (to_public_anchor db)

let get_anchors db (src_doc : App_types.Src_doc.t) ~start ~end_ : anchor list
    =
  let doc_meta = get_doc_meta_exn db src_doc in
  DB.Anchors.get_overlapping db doc_meta.doc_id ~start ~end_
  |> List.map (to_public_anchor db)

let get_all_anchors db : anchor list =
  DB.Anchors.get_all db |> List.map (to_public_anchor db)

let get_all_current_anchors db : anchor list =
  DB.Anchors.get_all_current db |> List.map (to_public_anchor db)

let get_all_stale_anchors db : anchor list =
  DB.Anchors.get_all_stale db |> List.map (to_public_anchor db)

let get_all_anchors_needing_review db : anchor list =
  get_all_stale_anchors db |> List.filter (fun (a : anchor) -> a.needs_review)

let acknowledge_anchor db (anchor_id : T.anchor_id) : anchor =
  let a =
    match DB.Anchors.get db anchor_id with
    | Some a -> a
    | None ->
        ksprintf failwith "No such anchor: %s"
          (App_types.Anchor_id.to_string anchor_id)
  in
  let doc_meta =
    match DB.Documents.get_by_id db a.doc_id with
    | Some m -> m
    | None ->
        failwith "internal error: anchor references a nonexistent document"
  in
  DB.Anchors.acknowledge db anchor_id ~revision:doc_meta.revision;
  match get_anchor db anchor_id with
  | Some a -> a
  | None -> failwith "internal error: anchor disappeared during acknowledge"

type search_result = {
  doc_id : doc_id;
  source_doc : T.source_doc;
  range : T.range;
  raw_contents : string;
  num_hits : int;
  coverage : int;
  source : Util.Text_source.t;
}

let search db snippet : search_result list =
  let anchor_norm = normalize_whitespace snippet in
  if String.length anchor_norm.text < min_query_length then
    ksprintf failwith
      "Query snippet is too short: after collapsing whitespace, must be at \
       least %d byte(s)"
        | By_id doc_id -> App_types.Doc_id.to_string doc_id
      in
      ksprintf failwith "Not indexed: %s" ref_str
  | Some (doc_meta, DB.Deleted) ->
      ksprintf failwith
        "Document %s was deleted (see 'skl text document put' to re-add it)"
        (App_types.Src_doc.show_source_doc doc_meta.source_doc)
  | Some (doc_meta, DB.Active contents) ->
      ( doc_meta,
        { Util.Text_source.name = doc_meta.source_doc.locator; contents } )

(* Replace derived indexes and relocate anchors as one transaction.
   Callers must also include the document revision update in that
   transaction so any exception rolls back the entire edit. *)
let reindex_and_relocate db ~doc_id ~(contents : DB.doc_contents) :
    doc_meta * anchor list =
  DB.Shingles.delete_doc db doc_id;
  DB.Documents_fuzzy.index db ~doc_id ~contents ~force:false;
  (match contents with
  | DB.Active c -> Anchor.index_shingles db ~doc_id c
  | DB.Deleted -> ());
  let doc_meta =
    match DB.Documents.get_by_id db doc_id with
    | Some m -> m
    | None -> failwith "internal error: just-registered document not found"
  in
  let changed =
    Anchor.relocate_stale_anchors db ~doc_id ~doc_revision:doc_meta.revision
  in
  (doc_meta, changed)

let add_file db (src_doc : App_types.Src_doc.t)
    (text_source : Util.Text_source.t) : doc_meta * anchor list =
  let source_doc = App_types.Src_doc.to_source_doc src_doc in
  Sqlite_util.Connect.with_transaction db (fun () ->
      ensure_source_declared db source_doc.source;
      let doc_id =
        DB.Documents.create_or_update db ~source:source_doc.source
          ~locator:source_doc.locator
          ~contents:(DB.Active text_source.contents)
      in
      DB.Containers.index db ~doc_id src_doc;
      reindex_and_relocate db ~doc_id
        ~contents:(DB.Active text_source.contents))

let remove_document ?(strict = false) db (doc_ref : doc_ref) : anchor list =
  let doc_meta =
    match doc_ref with
    | By_locator src_doc ->
        let source_doc = App_types.Src_doc.to_source_doc src_doc in
        DB.Documents.get_by_locator db ~source:source_doc.source
          source_doc.locator
    | By_id doc_id -> DB.Documents.get_by_id db doc_id
  in
  match doc_meta with
  | None ->
      if strict then
        let ref_str =
          match doc_ref with
          | By_locator src_doc -> App_types.Src_doc.show src_doc
          | By_id doc_id -> App_types.Doc_id.to_string doc_id
        in
        ksprintf failwith "Not indexed: %s" ref_str
      else []
  | Some (meta : T.doc_meta) ->
      Sqlite_util.Connect.with_transaction db (fun () ->
          let doc_id =
            DB.Documents.create_or_update db ~source:meta.source_doc.source
              ~locator:meta.source_doc.locator ~contents:DB.Deleted
          in
          DB.Containers.delete_for_doc db doc_id;
          snd (reindex_and_relocate db ~doc_id ~contents:DB.Deleted))

(* Recompute derived indexes without changing content, revisions or anchors. *)
let reindex_all db : int =
  Sqlite_util.Connect.with_transaction db (fun () ->
      let docs = DB.Documents.get_all db in
      List.iter
        (fun ((doc_meta : T.doc_meta), contents) ->
          DB.Shingles.delete_doc db doc_meta.doc_id;
          DB.Documents_fuzzy.index db ~doc_id:doc_meta.doc_id ~contents
      acknowledged_revision =
        int_option_of_column stmt col_acknowledged_revision;
    }

  let select_cols =
    {|anchor_id, doc_id, doc_revision, doc_revision_attempt,
      "start", "end", last_author, raw_contents, acknowledged_revision|}

  let create db (a : Internal_types.anchor) : Internal_types.anchor =
    let anchor_id =
      exec_returning_one db
        {|INSERT INTO "anchors"
            (doc_id, doc_revision, doc_revision_attempt,
             "start", "end", last_author, raw_contents,
             acknowledged_revision)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?)
          RETURNING anchor_id|}
        [
          U.Int64 (A.Doc_id.to_int64 a.doc_id);
          U.Int64 (Int64.of_int a.doc_revision);
          U.Int64 (Int64.of_int a.doc_revision_attempt);
          U.Int64 (Int64.of_int a.range.start);
          U.Int64 (Int64.of_int a.range.end_);
          U.Text (Util.Text.validate_exn (author_to_string a.last_author));
          U.Blob a.raw_contents;
          param_of_int_option a.acknowledged_revision;
        ]
        ~f:(fun stmt ->
          A.Anchor_id.of_int64_exn (Sqlite3.column_int64 stmt 0))
    in
    { a with Internal_types.anchor_id }

  let get db (anchor_id : T.anchor_id) : Internal_types.anchor option =
    U.query_rows db
      (sprintf {|SELECT %s FROM "anchors" WHERE anchor_id = ?|} select_cols)
      [ U.Int64 (A.Anchor_id.to_int64 anchor_id) ]
      ~f:row_to_anchor
    |> function
    | [] -> None
    | x :: _ -> Some x

  let delete db (anchor_id : T.anchor_id) =
    U.exec_params db {|DELETE FROM "anchors" WHERE anchor_id = ?|}
      [ U.Int64 (A.Anchor_id.to_int64 anchor_id) ]

  let relocate db (a : Internal_types.anchor) =
    U.exec_params db
      {|UPDATE "anchors"
        SET doc_id = ?, doc_revision = ?, doc_revision_attempt = ?,
            "start" = ?, "end" = ?, last_author = ?, raw_contents = ?
        WHERE anchor_id = ?|}
      [
        U.Int64 (A.Doc_id.to_int64 a.doc_id);
        U.Int64 (Int64.of_int a.doc_revision);
        U.Int64 (Int64.of_int a.doc_revision_attempt);
        U.Int64 (Int64.of_int a.range.start);
        U.Int64 (Int64.of_int a.range.end_);
        U.Text (Util.Text.validate_exn (author_to_string a.last_author));
        U.Blob a.raw_contents;
        U.Int64 (A.Anchor_id.to_int64 a.anchor_id);
      ]

  let mark_attempt_failed db (anchor_id : T.anchor_id) ~doc_revision_attempt =
    U.exec_params db
      {|UPDATE "anchors" SET doc_revision_attempt = ? WHERE anchor_id = ?|}
      [
        U.Int64 (Int64.of_int doc_revision_attempt);
        U.Int64 (A.Anchor_id.to_int64 anchor_id);
      ]

  let acknowledge db (anchor_id : T.anchor_id) ~revision =
    U.exec_params db
      {|UPDATE "anchors" SET acknowledged_revision = ? WHERE anchor_id = ?|}
      [
        U.Int64 (Int64.of_int revision);
        U.Int64 (A.Anchor_id.to_int64 anchor_id);
      ]

  let get_overlapping db (doc_id : T.doc_id) ~start ~end_ :
      Internal_types.anchor list =
    U.query_rows db
      (sprintf
         {|SELECT %s FROM "anchors"
           WHERE doc_id = ? AND "start" < ? AND "end" > ?|}
         select_cols)
      [
        U.Int64 (A.Doc_id.to_int64 doc_id);
        U.Int64 (Int64.of_int end_);
        U.Int64 (Int64.of_int start);
      ]
      ~f:row_to_anchor

  let get_stale db (doc_id : T.doc_id) ~doc_revision :
      Internal_types.anchor list =
    U.query_rows db
      (sprintf
         {|SELECT %s FROM "anchors"
           WHERE doc_id = ? AND doc_revision_attempt < ?|}
         select_cols)
      [
        U.Int64 (A.Doc_id.to_int64 doc_id);
        U.Int64 (Int64.of_int doc_revision);
      ]
      ~f:row_to_anchor

  let get_all db : Internal_types.anchor list =
    U.query_rows db
      (sprintf {|SELECT %s FROM "anchors"|} select_cols)
      [] ~f:row_to_anchor

  let get_all_current db : Internal_types.anchor list =
    U.query_rows db
      (sprintf
         {|SELECT %s FROM "anchors"
           WHERE doc_revision = doc_revision_attempt|}
         select_cols)
      [] ~f:row_to_anchor

  let get_all_stale db : Internal_types.anchor list =
    U.query_rows db
      (sprintf
         {|SELECT %s FROM "anchors"
           WHERE doc_revision < doc_revision_attempt|}
         select_cols)
      [] ~f:row_to_anchor
end
  (** [anchor.anchor_id] is ignored: the database generates a new one. Returns
      [anchor] with [anchor_id] set to the generated value; every other field
      is stored as given, including [doc_revision_attempt] -- the caller
      decides that value (typically equal to [doc_revision] for a brand new
      anchor). *)

  val get : t -> T.anchor_id -> Internal_types.anchor option
  val delete : t -> T.anchor_id -> unit

  val relocate : t -> Internal_types.anchor -> unit
  (** Overwrites the anchor identified by [anchor.anchor_id] with every other
      field taken from [anchor]. Used for a successful (re)location, possibly
      to a different document than before. The caller decides
      [doc_revision_attempt] (typically equal to [doc_revision] on success).
  *)

  val mark_attempt_failed :
    t -> T.anchor_id -> doc_revision_attempt:int -> unit
  (** Record a failed attempt at relocating the anchor: only
      [doc_revision_attempt] is updated. The anchor keeps pointing at its last
      known location ("gone" state) in case it reappears later. *)

  val acknowledge : t -> T.anchor_id -> revision:int -> unit
  (** Sets [acknowledged_revision] to [revision]. *)

  val get_overlapping :
    t -> T.doc_id -> start:int -> end_:int -> Internal_types.anchor list

  val get_stale :
    t -> T.doc_id -> doc_revision:int -> Internal_types.anchor list
  (** Anchors currently on [doc_id] that haven't been reconciled with
      [doc_revision] yet, i.e. [doc_revision_attempt < doc_revision]. *)

  val get_all : t -> Internal_types.anchor list
  val get_all_current : t -> Internal_types.anchor list
  val get_all_stale : t -> Internal_types.anchor list
end

